+    'app.kubernetes.io/managed-by': MANAGED_BY,
+    'secsim.io/node': node.nodeId,
+  };
+  return {
+    metadata: { name: node.name, namespace, labels },
+    spec: {
+      replicas: 1,
+      selector: { matchLabels: { app: node.name } },
+      template: {
+        metadata: { labels },
+        spec: {
+          containers: [
+            {
+              name: node.name,
+              image: node.image,
+              ports: [{ containerPort: node.containerPort }],
+            },
+          ],
+        },
+      },
+    },
+  };
